#include <stdio.h>
#include <stdlib.h>

#define MAXN 1005

int A[MAXN][MAXN];
int B[MAXN][MAXN];
int height[MAXN];
int stack[MAXN];
int L_bound[MAXN];
int R_bound[MAXN];

int main() {
    int L, C;
    if (scanf("%d %d", &L, &C) != 2) return 0;

    for (int i = 0; i < L; i++) {
        for (int j = 0; j < C; j++) {
            scanf("%d", &A[i][j]);
        }
    }

    int rows = L - 1;
    int cols = C - 1;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if ((long long)A[i][j] + A[i + 1][j + 1] <= (long long)A[i][j + 1] + A[i + 1][j]) {
                B[i][j] = 1;
            } else {
                B[i][j] = 0;
            }
        }
    }

    long long max_ans = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (B[i][j] == 1) {
                height[j]++;
            } else {
                height[j] = 0;
            }
        }

        int top = -1;
        for (int j = 0; j < cols; j++) {
            while (top >= 0 && height[stack[top]] >= height[j]) {
                top--;
            }
            L_bound[j] = (top >= 0) ? stack[top] + 1 : 0;
            stack[++top] = j;
        }

        top = -1;
        for (int j = cols - 1; j >= 0; j--) {
            while (top >= 0 && height[stack[top]] >= height[j]) {
                top--;
            }
            R_bound[j] = (top >= 0) ? stack[top] - 1 : cols - 1;
            stack[++top] = j;
        }

        for (int j = 0; j < cols; j++) {
            if (height[j] > 0) {
                long long h_prime = height[j];
                long long w_prime = R_bound[j] - L_bound[j] + 1;
                long long area = (h_prime + 1) * (w_prime + 1);
                if (area > max_ans) {
                    max_ans = area;
                }
            }
        }
    }

    printf("%lld\n", max_ans);

    return 0;
}
